// HaifyControllerServer is the server API for HaifyController service.
// All implementations must embed UnimplementedHaifyControllerServer
// for forward compatibility.
//
// Haify Controller Service
type HaifyControllerServer interface {
	// Pool operations
	CreatePool(context.Context, *CreatePoolRequest) (*CreatePoolResponse, error)
	DeletePool(context.Context, *DeletePoolRequest) (*DeletePoolResponse, error)
	GetPool(context.Context, *GetPoolRequest) (*GetPoolResponse, error)
	ListPools(context.Context, *ListPoolsRequest) (*ListPoolsResponse, error)
	// Storage upkeep: trimming, disks, and long-running storage jobs.
	TrimPools(context.Context, *TrimPoolsRequest) (*TrimPoolsResponse, error)
	ListPoolDisks(context.Context, *ListPoolDisksRequest) (*ListPoolDisksResponse, error)
	// ListNodeDisks lists the disks on the nodes and whether a pool can use
	// each one: empty, holding only old data, in a pool, or in use.
	ListNodeDisks(context.Context, *ListNodeDisksRequest) (*ListNodeDisksResponse, error)
	// ShipResource copies a resource to another Haify cluster: a snapshot of
	// every volume streams straight into a new resource there. It runs as a
	// storage job.
	ShipResource(context.Context, *ShipResourceRequest) (*StorageJobResponse, error)
	// PrepareShipReceive and FinishShipReceive are the receiving cluster's half
	// of a ship, called by the sending controller.
	PrepareShipReceive(context.Context, *PrepareShipReceiveRequest) (*PrepareShipReceiveResponse, error)
	FinishShipReceive(context.Context, *FinishShipReceiveRequest) (*FinishShipReceiveResponse, error)
	RemovePoolDisk(context.Context, *RemovePoolDiskRequest) (*StorageJobResponse, error)
	ReplacePoolDisk(context.Context, *ReplacePoolDiskRequest) (*StorageJobResponse, error)
	MoveVolume(context.Context, *MoveVolumeRequest) (*StorageJobResponse, error)
	ListStorageJobs(context.Context, *ListStorageJobsRequest) (*ListStorageJobsResponse, error)
	AddDiskToPool(context.Context, *AddDiskToPoolRequest) (*AddDiskToPoolResponse, error)
	// Node operations
	RegisterNode(context.Context, *RegisterNodeRequest) (*RegisterNodeResponse, error)
	UnregisterNode(context.Context, *UnregisterNodeRequest) (*UnregisterNodeResponse, error)
	SetNodeLabels(context.Context, *SetNodeLabelsRequest) (*SetNodeLabelsResponse, error)
	SetNodeAddress(context.Context, *SetNodeAddressRequest) (*SetNodeAddressResponse, error)
	// SetNodeReplicationPaths sets the further addresses DRBD may use for a
	// node and rewrites every resource it takes part in.
	SetNodeReplicationPaths(context.Context, *SetNodeReplicationPathsRequest) (*SetNodeAddressResponse, error)
	GetNode(context.Context, *GetNodeRequest) (*GetNodeResponse, error)
	ListNodes(context.Context, *ListNodesRequest) (*ListNodesResponse, error)
	HealthCheck(context.Context, *HealthCheckRequest) (*HealthCheckResponse, error)
	// Resource operations
	CreateResource(context.Context, *CreateResourceRequest) (*CreateResourceResponse, error)
	AdoptResource(context.Context, *AdoptResourceRequest) (*AdoptResourceResponse, error)
	DeleteResource(context.Context, *DeleteResourceRequest) (*DeleteResourceResponse, error)
	GetResource(context.Context, *GetResourceRequest) (*GetResourceResponse, error)
	ListResources(context.Context, *ListResourcesRequest) (*ListResourcesResponse, error)
	CreateResourceProfile(context.Context, *CreateResourceProfileRequest) (*CreateResourceProfileResponse, error)
	GetResourceProfile(context.Context, *GetResourceProfileRequest) (*GetResourceProfileResponse, error)
	ListResourceProfiles(context.Context, *ListResourceProfilesRequest) (*ListResourceProfilesResponse, error)
	DeleteResourceProfile(context.Context, *DeleteResourceProfileRequest) (*DeleteResourceProfileResponse, error)
	SetResourceProfileOptions(context.Context, *SetResourceProfileOptionsRequest) (*SetResourceProfileOptionsResponse, error)
	AdjustResourceProfile(context.Context, *AdjustResourceProfileRequest) (*AdjustResourceProfileResponse, error)
	GetResourceProfileMaxSize(context.Context, *GetResourceProfileMaxSizeRequest) (*GetResourceProfileMaxSizeResponse, error)
	SetResourceProfile(context.Context, *SetResourceProfileRequest) (*SetResourceProfileResponse, error)
	AddVolume(context.Context, *AddVolumeRequest) (*AddVolumeResponse, error)
	RemoveVolume(context.Context, *RemoveVolumeRequest) (*RemoveVolumeResponse, error)
	// Renames a resource that nothing else refers to by name: offline (not
	// Primary anywhere), with no HA config, gateway, schedule, backups or
	// snapshots, not WAN-replicated or encrypted. Its data, node ids and port
	// are kept. The Proxmox plugin uses it to reassign disks and make templates.
	// Resource snapshots: every volume on every diskful replica, taken with
	// I/O suspended across them, so a rollback restores all replicas together
	// and resyncs nothing. Backing snapshots are "<backing>_snap_<name>".
	CreateResourceSnapshot(context.Context, *CreateResourceSnapshotRequest) (*CreateResourceSnapshotResponse, error)
	ListResourceSnapshots(context.Context, *ListResourceSnapshotsRequest) (*ListResourceSnapshotsResponse, error)
	RollbackResourceSnapshot(context.Context, *RollbackResourceSnapshotRequest) (*RollbackResourceSnapshotResponse, error)
	DeleteResourceSnapshot(context.Context, *DeleteResourceSnapshotRequest) (*DeleteResourceSnapshotResponse, error)
	RenameResource(context.Context, *RenameResourceRequest) (*RenameResourceResponse, error)
	ResizeVolume(context.Context, *ResizeVolumeRequest) (*ResizeVolumeResponse, error)
	UpdateResourceOptions(context.Context, *UpdateResourceOptionsRequest) (*UpdateResourceOptionsResponse, error)
	// Brings every participant's copy of a resource's DRBD config back into
	// agreement, tiebreakers and diskless clients included, and applies it.
	RepairResource(context.Context, *RepairResourceRequest) (*RepairResourceResponse, error)
	ResourceStatus(context.Context, *ResourceStatusRequest) (*ResourceStatusResponse, error)
	SetPrimary(context.Context, *SetPrimaryRequest) (*SetPrimaryResponse, error)
	SetSecondary(context.Context, *SetSecondaryRequest) (*SetSecondaryResponse, error)
	SetDualPrimary(context.Context, *SetDualPrimaryRequest) (*SetDualPrimaryResponse, error)
	AttachDisklessClient(context.Context, *AttachDisklessClientRequest) (*AttachDisklessClientResponse, error)
	DetachDisklessClient(context.Context, *DetachDisklessClientRequest) (*DetachDisklessClientResponse, error)
	// Labels on a resource: the keys in labels are set, then the keys in remove
	// are deleted. Integrations mark what they run on a resource this way, e.g.
	// haify.libvirt/domain=<guest>.
	SetResourceLabels(context.Context, *SetResourceLabelsRequest) (*SetResourceLabelsResponse, error)
	CreateFilesystem(context.Context, *CreateFilesystemRequest) (*CreateFilesystemResponse, error)
	MountResource(context.Context, *MountResourceRequest) (*MountResourceResponse, error)
	UnmountResource(context.Context, *UnmountResourceRequest) (*UnmountResourceResponse, error)
	MakeHa(context.Context, *MakeHaRequest) (*MakeHaResponse, error)
	EvictHa(context.Context, *EvictHaRequest) (*EvictHaResponse, error)
	// Orders where drbd-reactor starts an HA resource (preferred-nodes). A
	// preference, not a fence; DRBD quorum is what prevents split brain.
	SetHaPreferredNodes(context.Context, *SetHaPreferredNodesRequest) (*SetHaPreferredNodesResponse, error)
	SetTiebreaker(context.Context, *SetTiebreakerRequest) (*SetTiebreakerResponse, error)
	// Encrypted DRBD replication: prepare nodes (key, certificate from the
	// controller's replication CA, tlshd), report their readiness, and switch a
	// resource's connections over one link at a time.
	SetupReplicationTLS(context.Context, *SetupReplicationTLSRequest) (*ReplicationTLSResponse, error)
	GetReplicationTLSStatus(context.Context, *GetReplicationTLSStatusRequest) (*ReplicationTLSResponse, error)
	SetResourceTLS(context.Context, *SetResourceTLSRequest) (*SetResourceTLSResponse, error)
	AddDR(context.Context, *AddDRRequest) (*AddDRResponse, error)
	AddReplica(context.Context, *AddReplicaRequest) (*AddReplicaResponse, error)
	RemoveReplica(context.Context, *RemoveReplicaRequest) (*RemoveReplicaResponse, error)
	DeleteHa(context.Context, *DeleteHaRequest) (*DeleteHaResponse, error)
	GetHa(context.Context, *GetHaRequest) (*GetHaResponse, error)
	ListHa(context.Context, *ListHaRequest) (*ListHaResponse, error)
	GetHaStatus(context.Context, *GetHaStatusRequest) (*GetHaStatusResponse, error)
	// HA OCF resource-agent discovery and drbd-reactor promoter TOML editing.
	ListResourceAgents(context.Context, *ListResourceAgentsRequest) (*ListResourceAgentsResponse, error)
	GetResourceAgentMetadata(context.Context, *GetResourceAgentMetadataRequest) (*GetResourceAgentMetadataResponse, error)
	GetHaToml(context.Context, *GetHaTomlRequest) (*GetHaTomlResponse, error)
	SyncHaToml(context.Context, *SyncHaTomlRequest) (*SyncHaTomlResponse, error)
	// Controller self-HA operations: make the controller itself highly
	// available on its own DRBD + drbd-reactor machinery.
	EnableSelfHa(context.Context, *EnableSelfHaRequest) (*EnableSelfHaResponse, error)
	DisableSelfHa(context.Context, *DisableSelfHaRequest) (*DisableSelfHaResponse, error)
	GetSelfHaStatus(context.Context, *GetSelfHaStatusRequest) (*GetSelfHaStatusResponse, error)
	// Snapshot operations. Volume identifiers are "<pool>/<lv>" paths, so the
	// REST bindings need the two-segment pattern {volume=*/*}; a plain
	// {volume} never matches a value containing a slash. The single-segment
	// binding is kept for backward compatibility.
	CreateSnapshot(context.Context, *CreateSnapshotRequest) (*CreateSnapshotResponse, error)
	DeleteSnapshot(context.Context, *DeleteSnapshotRequest) (*DeleteSnapshotResponse, error)
	RestoreSnapshot(context.Context, *RestoreSnapshotRequest) (*RestoreSnapshotResponse, error)
	ListSnapshots(context.Context, *ListSnapshotsRequest) (*ListSnapshotsResponse, error)
	// CreateSnapshotGroup takes one-node snapshots (as CreateSnapshot does) of
	// several volumes at the same instant, so an application spread over them
	// gets a crash-consistent set. I/O is suspended on every member's resource
	// (its Primary first) while the snapshots are taken, under a transient
	// timer on each node that resumes it whatever happens to the controller.
	// All or nothing: a member that fails removes the ones already taken. The
	// CSI driver's VolumeGroupSnapshot is built on it.
	CreateSnapshotGroup(context.Context, *CreateSnapshotGroupRequest) (*CreateSnapshotGroupResponse, error)
	// PopulateVolume copies a snapshot, or a source block device such as another
	// resource's backing volume, into an ALREADY-CREATED, still-empty DRBD
	// resource. Unlike RestoreSnapshot — which merges a snapshot back into its own
	// origin in place — this fills a *different*, new volume, which is what CSI
	// restore-from-snapshot and volume cloning need.
	//
	// The copy is written to the target's DRBD device (not its backing LV) on a
	// node that holds a replica, so DRBD replicates it to every peer for free.
	PopulateVolume(context.Context, *PopulateVolumeRequest) (*PopulateVolumeResponse, error)
	// Snapshot schedule operations (cron-driven snapshots + GFS retention)
	CreateSnapshotSchedule(context.Context, *CreateSnapshotScheduleRequest) (*CreateSnapshotScheduleResponse, error)
	ListSnapshotSchedules(context.Context, *ListSnapshotSchedulesRequest) (*ListSnapshotSchedulesResponse, error)
	DeleteSnapshotSchedule(context.Context, *DeleteSnapshotScheduleRequest) (*DeleteSnapshotScheduleResponse, error)
	// Freezing a schedule keeps it snapshotting but stops all pruning, and locks
	// every scheduled snapshot of the resource until the freeze ends. The
	// write-anomaly detector freezes one when it fires. A freeze is only ever
	// extended by Freeze; Unfreeze ends it early.
	FreezeSnapshotSchedule(context.Context, *FreezeSnapshotScheduleRequest) (*FreezeSnapshotScheduleResponse, error)
	UnfreezeSnapshotSchedule(context.Context, *UnfreezeSnapshotScheduleRequest) (*UnfreezeSnapshotScheduleResponse, error)
	// Backup operations: shipping point-in-time copies OFF the cluster to an
	// S3-compatible object store, an SMB share or a WebDAV endpoint.
	//
	// Distinct from snapshots (same pool, lost with the machine) and from WAN DR
	// (a replica, where a delete replicates). After the first full image, a
	// backup of a thin volume is incremental: only blocks changed since the last
	// backup to the same target are shipped.
	AddBackupTarget(context.Context, *AddBackupTargetRequest) (*AddBackupTargetResponse, error)
	ListBackupTargets(context.Context, *ListBackupTargetsRequest) (*ListBackupTargetsResponse, error)
	DeleteBackupTarget(context.Context, *DeleteBackupTargetRequest) (*DeleteBackupTargetResponse, error)
	CreateBackup(context.Context, *CreateBackupRequest) (*CreateBackupResponse, error)
	ListBackups(context.Context, *ListBackupsRequest) (*ListBackupsResponse, error)
	RestoreBackup(context.Context, *RestoreBackupRequest) (*RestoreBackupResponse, error)
	DeleteBackup(context.Context, *DeleteBackupRequest) (*DeleteBackupResponse, error)
	// ImportBackups rebuilds backup records from the manifests on a target, for
	// a controller that lost its database or a cluster restoring another's.
	ImportBackups(context.Context, *ImportBackupsRequest) (*ImportBackupsResponse, error)
	CreateBackupSchedule(context.Context, *CreateBackupScheduleRequest) (*CreateBackupScheduleResponse, error)
	ListBackupSchedules(context.Context, *ListBackupSchedulesRequest) (*ListBackupSchedulesResponse, error)
	DeleteBackupSchedule(context.Context, *DeleteBackupScheduleRequest) (*DeleteBackupScheduleResponse, error)
	RunBackupSchedule(context.Context, *RunBackupScheduleRequest) (*RunBackupScheduleResponse, error)
	// Gateway operations
	CreateNFSGateway(context.Context, *CreateNFSGatewayRequest) (*CreateNFSGatewayResponse, error)
	CreateISCSIGateway(context.Context, *CreateISCSIGatewayRequest) (*CreateISCSIGatewayResponse, error)
	CreateNVMeGateway(context.Context, *CreateNVMeGatewayRequest) (*CreateNVMeGatewayResponse, error)
	DeleteGateway(context.Context, *DeleteGatewayRequest) (*DeleteGatewayResponse, error)
	GetGateway(context.Context, *GetGatewayRequest) (*GetGatewayResponse, error)
	ListGateways(context.Context, *ListGatewaysRequest) (*ListGatewaysResponse, error)
	StartGateway(context.Context, *StartGatewayRequest) (*StartGatewayResponse, error)
	StopGateway(context.Context, *StopGatewayRequest) (*StopGatewayResponse, error)
	AddNFSExport(context.Context, *AddNFSExportRequest) (*AddNFSExportResponse, error)
	RemoveNFSExport(context.Context, *RemoveNFSExportRequest) (*RemoveNFSExportResponse, error)
	ListNFSExports(context.Context, *ListNFSExportsRequest) (*ListNFSExportsResponse, error)
	// SMB gateway (workgroup edition): a standalone Samba server per resource,
	// its users and shares kept on the gateway's state volume.
	CreateSMBGateway(context.Context, *CreateSMBGatewayRequest) (*CreateSMBGatewayResponse, error)
	AddSMBShare(context.Context, *AddSMBShareRequest) (*AddSMBShareResponse, error)
	RemoveSMBShare(context.Context, *RemoveSMBShareRequest) (*RemoveSMBShareResponse, error)
	ListSMBShares(context.Context, *ListSMBSharesRequest) (*ListSMBSharesResponse, error)
	SetSMBUser(context.Context, *SetSMBUserRequest) (*SetSMBUserResponse, error)
	RemoveSMBUser(context.Context, *RemoveSMBUserRequest) (*RemoveSMBUserResponse, error)
	ListSMBUsers(context.Context, *ListSMBUsersRequest) (*ListSMBUsersResponse, error)
	AddISCSILUN(context.Context, *AddISCSILUNRequest) (*AddISCSILUNResponse, error)
	RemoveISCSILUN(context.Context, *RemoveISCSILUNRequest) (*RemoveISCSILUNResponse, error)
	ListISCSILUNs(context.Context, *ListISCSILUNsRequest) (*ListISCSILUNsResponse, error)
	AddISCSIInitiator(context.Context, *AddISCSIInitiatorRequest) (*AddISCSIInitiatorResponse, error)
	RemoveISCSIInitiator(context.Context, *RemoveISCSIInitiatorRequest) (*RemoveISCSIInitiatorResponse, error)
	ListISCSIInitiators(context.Context, *ListISCSIInitiatorsRequest) (*ListISCSIInitiatorsResponse, error)
	SetISCSIChap(context.Context, *SetISCSIChapRequest) (*SetISCSIChapResponse, error)
	GetISCSIChap(context.Context, *GetISCSIChapRequest) (*GetISCSIChapResponse, error)
	AddNVMeNamespace(context.Context, *AddNVMeNamespaceRequest) (*AddNVMeNamespaceResponse, error)
	RemoveNVMeNamespace(context.Context, *RemoveNVMeNamespaceRequest) (*RemoveNVMeNamespaceResponse, error)
	ListNVMeNamespaces(context.Context, *ListNVMeNamespacesRequest) (*ListNVMeNamespacesResponse, error)
	AddNVMeHost(context.Context, *AddNVMeHostRequest) (*AddNVMeHostResponse, error)
	RemoveNVMeHost(context.Context, *RemoveNVMeHostRequest) (*RemoveNVMeHostResponse, error)
	ListNVMeHosts(context.Context, *ListNVMeHostsRequest) (*ListNVMeHostsResponse, error)
	// ZFS operations
	CreateZFSPool(context.Context, *CreateZFSPoolRequest) (*CreateZFSPoolResponse, error)
	DeleteZFSPool(context.Context, *DeleteZFSPoolRequest) (*DeleteZFSPoolResponse, error)
	// Listing ZFS pools was the one RPC in the ZFS pool CRUD triple with no HTTP
	// binding, so it was reachable over gRPC but absent from the REST API and
	// from the generated OpenAPI document. Create and Delete were both bound.
	ListZFSpools(context.Context, *ListZFSPoolsRequest) (*ListZFSPoolsResponse, error)
	CreateZFSDataset(context.Context, *CreateZFSDatasetRequest) (*CreateZFSDatasetResponse, error)
	CreateZFSVolume(context.Context, *CreateZFSVolumeRequest) (*CreateZFSVolumeResponse, error)
	ResizeZFSVolume(context.Context, *ResizeZFSVolumeRequest) (*ResizeZFSVolumeResponse, error)
	DeleteZFSDataset(context.Context, *DeleteZFSDatasetRequest) (*DeleteZFSDatasetResponse, error)
	// ZFS Snapshot operations
	// ZFS snapshot identifiers are "<pool>/<dataset>" (and
	// "<pool>/<dataset>@<snap>") paths; single-segment {param} patterns never
	// match values containing '/', so two-segment bindings come first.
	// Deeply nested datasets (pool/a/b) are not reachable over REST.
	CreateZFSSnapshot(context.Context, *CreateZFSSnapshotRequest) (*CreateZFSSnapshotResponse, error)
	DeleteZFSSnapshot(context.Context, *DeleteZFSSnapshotRequest) (*DeleteZFSSnapshotResponse, error)
	ListZFSSnapshots(context.Context, *ListZFSSnapshotsRequest) (*ListZFSSnapshotsResponse, error)
	RestoreZFSSnapshot(context.Context, *RestoreZFSSnapshotRequest) (*RestoreZFSSnapshotResponse, error)
	CloneZFSSnapshot(context.Context, *CloneZFSSnapshotRequest) (*CloneZFSSnapshotResponse, error)
	// LVM Snapshot operations
	CreateLvmSnapshot(context.Context, *CreateLvmSnapshotRequest) (*CreateLvmSnapshotResponse, error)
	DeleteLvmSnapshot(context.Context, *DeleteLvmSnapshotRequest) (*DeleteLvmSnapshotResponse, error)
	ListLvmSnapshots(context.Context, *ListLvmSnapshotsRequest) (*ListLvmSnapshotsResponse, error)
	RestoreLvmSnapshot(context.Context, *RestoreLvmSnapshotRequest) (*RestoreLvmSnapshotResponse, error)
	// Self-healing (see docs/user-guide.md "Self-healing"). MoveReplica adds
	// the new replica and removes the old one once the new one is UpToDate.
	// PlanRebalance proposes moves from the fullest node; apply runs them one
	// at a time. MarkNodeLost removes the replicas of a node that will not
	// return; RestoreNode cleans what a returned node holds of resources it is
	// no longer part of and lets it take replicas again.
	// Caps an NFS export directory with an ext4 project quota (gateways
	// created from this version on); size 0 removes the cap.
	SetNFSExportQuota(context.Context, *SetNFSExportQuotaRequest) (*SetNFSExportQuotaResponse, error)
	MoveReplica(context.Context, *MoveReplicaRequest) (*MoveReplicaResponse, error)
	PlanRebalance(context.Context, *PlanRebalanceRequest) (*PlanRebalanceResponse, error)
	MarkNodeLost(context.Context, *MarkNodeLostRequest) (*MarkNodeLostResponse, error)
	RestoreNode(context.Context, *RestoreNodeRequest) (*RestoreNodeResponse, error)
	DrainNode(context.Context, *DrainNodeRequest) (*DrainNodeResponse, error)
	UndrainNode(context.Context, *UndrainNodeRequest) (*UndrainNodeResponse, error)
	// ConvertPoolToThin rebuilds one node's LVM pool as a thin pool, in place.
	// Thick pools cannot hold a snapshot history: each snapshot reserves a fixed
	// COW area whether anything changes or not.
	ConvertPoolToThin(context.Context, *ConvertPoolToThinRequest) (*ConvertPoolToThinResponse, error)
	// Storage tiering: put an SSD/NVMe device in front of one node's LVM pool
	// with lvmcache. The cache serves the whole pool, and defaults to
	// writethrough because a writeback cache holds acknowledged writes that no
	// other node has yet.
	AddPoolCache(context.Context, *AddPoolCacheRequest) (*AddPoolCacheResponse, error)
	RemovePoolCache(context.Context, *RemovePoolCacheRequest) (*RemovePoolCacheResponse, error)
	// Audit trail: who called what, when, and whether it was allowed. Persisted
	// in the database, which lives on the controller's replicated volume, so the
	// history follows the controller across a failover instead of being split
	// across the journals of whichever nodes happened to be active.
	ListAuditEvents(context.Context, *ListAuditEventsRequest) (*ListAuditEventsResponse, error)
	// The controller's own log output, from an in-memory ring buffer. Deliberately
	// not persisted: this is for watching what a running controller is doing, and
	// a controller that has moved has nothing useful to say about its old node.
	ListControllerLogs(context.Context, *ListControllerLogsRequest) (*ListControllerLogsResponse, error)
	// The journals and kernel messages the controller does not hold.
	//
	// ListControllerLogs above is the controller's own ring buffer, and almost
	// nothing that breaks DRBD appears in it: a promoter that could not start its
	// target, a resource that will not connect, a kernel that refused the module,
	// an LVM pool with no space left. Those are on the nodes, and until now the
	// only way to read them was for a person to ssh in.
	//
	// The collectors are a fixed table, named and read-only. This is deliberately
	// not a command channel: a request names collectors, never a command line, so
	// an unknown name is reported back and nothing is run. See
	// pkg/controller/diagnostics.go for the table and what each one reads.
	CollectNodeDiagnostics(context.Context, *CollectNodeDiagnosticsRequest) (*CollectNodeDiagnosticsResponse, error)
	// Operational notifications: a replica degraded, a resource's Primary moved,
	// a node stopped answering. ListEvents serves the controller's bounded
	// in-memory history — enough to see what just happened, not an archive. The
	// durable record of who did what is ListAuditEvents.
	ListEvents(context.Context, *ListEventsRequest) (*ListEventsResponse, error)
	// Notification channels: where alerts are delivered. These live in the
	// controller database rather than in controller.toml so they can be changed
	// from the UI while the controller runs — reconfiguring alerting by editing a
	// file and restarting means a deliberate window with no alerting at all.
	//
	// A channel has a kind, because a chat service does not accept an arbitrary
	// JSON document: Feishu, Slack, WeCom and DingTalk each define their own
	// message envelope and reject anything else, and Feishu, WeCom and DingTalk
	// do it inside an HTTP 200.
	ListNotifyChannels(context.Context, *ListNotifyChannelsRequest) (*ListNotifyChannelsResponse, error)
	SaveNotifyChannel(context.Context, *SaveNotifyChannelRequest) (*SaveNotifyChannelResponse, error)
	DeleteNotifyChannel(context.Context, *DeleteNotifyChannelRequest) (*DeleteNotifyChannelResponse, error)
	// TestNotifyChannel delivers one synthetic message to a single channel and
	// reports what the far end actually said, including a rejection returned
	// inside a 200. It does not go through the event bus, so it neither pages the
	// other channels nor appears in the event history.
	TestNotifyChannel(context.Context, *TestNotifyChannelRequest) (*TestNotifyChannelResponse, error)
	// Cluster inspection: deterministic checks of everything around the alerts —
	// replicas stuck mid-handshake, alerts that reach no channel, node clocks,
	// disks and addresses, pool growth, late backups, Self-HA readiness,
	// certificate expiry, leftovers. RunInspection runs one now and waits for
	// the report; it changes nothing on the cluster. A run already in progress
	// is not overlapped: the call fails instead.
	RunInspection(context.Context, *RunInspectionRequest) (*RunInspectionResponse, error)
	// ListInspections lists stored reports, newest first, without their checks.
	ListInspections(context.Context, *ListInspectionsRequest) (*ListInspectionsResponse, error)
	// GetInspection returns one stored report; id "latest" (or empty) is the
	// newest.
	GetInspection(context.Context, *GetInspectionRequest) (*GetInspectionResponse, error)
	// RepairWanProxy reconciles a WAN resource's replication tunnels with what
	// the controller currently believes its nodes are: it re-provisions the legs
	// that should exist and removes instances left behind by a node that was
	// renumbered or removed. Safe to run on a healthy resource — it converges.
	RepairWanProxy(context.Context, *RepairWanProxyRequest) (*RepairWanProxyResponse, error)
	DRFailback(context.Context, *DRFailbackRequest) (*DRFailbackResponse, error)
	SetWanEndpoint(context.Context, *SetWanEndpointRequest) (*SetWanEndpointResponse, error)
	// SetWanTuning changes a WAN resource's proxy buffer and compression, and
	// restarts its tunnels on the new settings.
	SetWanTuning(context.Context, *SetWanTuningRequest) (*SetWanTuningResponse, error)
	// GetWanSizing weighs a resource's measured write rates, compressibility and
	// a link bandwidth, and says whether the link carries the workload, needs the
	// buffer, needs compression, or cannot keep up (ship snapshots instead), and
	// how big the buffer should be. Works for LAN resources too: whether to put
	// one on the WAN is the first question.
	GetWanSizing(context.Context, *GetWanSizingRequest) (*GetWanSizingResponse, error)
	VerifyResource(context.Context, *VerifyResourceRequest) (*VerifyResourceResponse, error)
	// WatchEvents streams notifications as they happen, so an operator (or the
	// web UI, or a script) can react without polling. Over REST this is a
	// newline-delimited JSON stream; `curl -N .../v1/events/watch` works.
	//
	// A watcher that cannot keep up loses events rather than blocking the
	// controller. Event.id is monotonic across the whole stream, so a gap in it
	// is how a client detects that it fell behind.
	WatchEvents(*WatchEventsRequest, grpc.ServerStreamingServer[Event]) error
	// Role-based access control: the caller's identity, the effective policy,
	// and user management. gRPC only, so they share the API's transport
	// security; the web UI reaches the same operations through hand-written
	// REST routes under /v1/rbac. Policy listing and user changes require the
	// administrator role. Each returns enabled=false when [rbac] is off.
	GetRbacWhoami(context.Context, *GetRbacWhoamiRequest) (*GetRbacWhoamiResponse, error)
	ListRbacPolicies(context.Context, *ListRbacPoliciesRequest) (*ListRbacPoliciesResponse, error)
	CreateRbacUser(context.Context, *CreateRbacUserRequest) (*CreateRbacUserResponse, error)
	DeleteRbacUser(context.Context, *DeleteRbacUserRequest) (*DeleteRbacUserResponse, error)
	SetRbacUserRole(context.Context, *SetRbacUserRoleRequest) (*SetRbacUserRoleResponse, error)
	// Two-person approval ([rbac.approval]). A call on the approval list made
	// without an approval fails with FAILED_PRECONDITION and leaves a pending
	// request; once a different user with the approve right approves it, the
	// same caller repeats the identical call and it runs, once.
	ListApprovals(context.Context, *ListApprovalsRequest) (*ListApprovalsResponse, error)
	ApproveRequest(context.Context, *ApproveRequestRequest) (*ApproveRequestResponse, error)
	RejectRequest(context.Context, *RejectRequestRequest) (*RejectRequestResponse, error)
	// Database applications (`haify app`): a single-instance PostgreSQL, MySQL/
	// MariaDB or Redis on a resource's DRBD volume, failed over by drbd-reactor
	// (mount, database unit, service IP last). CreateApp returns the generated
	// password once; it is kept only on the volume, readable by root.
	CreateApp(context.Context, *CreateAppRequest) (*CreateAppResponse, error)
	ListApps(context.Context, *ListAppsRequest) (*ListAppsResponse, error)
	GetAppStatus(context.Context, *GetAppStatusRequest) (*GetAppStatusResponse, error)
	// Takes the app out of drbd-reactor's hands and stops it. The resource and
	// its data are kept unless delete_data is set.
	DeleteApp(context.Context, *DeleteAppRequest) (*DeleteAppResponse, error)
	// Planned switchover: the app's node stops it and another replica takes over.
	FailoverApp(context.Context, *FailoverAppRequest) (*FailoverAppResponse, error)
	// Freezes the database on its node (with a node-side thaw watchdog), takes
	// a resource snapshot on every replica, and thaws.
	SnapshotApp(context.Context, *SnapshotAppRequest) (*SnapshotAppResponse, error)
	mustEmbedUnimplementedHaifyControllerServer()
}

